class Solution {
public:
    int countNumbersWithUniqueDigits(int n) {
        int limit = 1;
        for (int i = 0; i < n; i++) limit *= 10;
        int ans = 0;
        for (int x = 0; x < limit; x++) {
            bool seen[10] = {false};
            int v = x;
            bool ok = true;
            do {
                int d = v % 10;
                if (seen[d]) { ok = false; break; }
                seen[d] = true;
                v /= 10;
            } while (v > 0);
            if (ok) ans++;
        }
        return ans;
    }
};

