var countNumbersWithUniqueDigits = function(n) {
    let ans = 0;
    const limit = Math.pow(10, n);
    for (let x = 0; x < limit; x++) {
        const s = String(x);
        if (new Set(s).size === s.length) ans++;
    }
    return ans;
};

